// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { latestBinding, syncDialogElement } from "../../../main/frontend/graph-explorer/workspace-library.ts";

const source = { basePath: "/workbench", serverIdentity: `sha256:${"c".repeat(64)}`, repositoryId: "repo" };
const saved = (revision, name = "Graph") => ({ id: "g", name, createdAt: "2026-10-22T00:00:00.000Z",
  updatedAt: "2026-10-22T00:00:00.000Z", revision, source, nodeCount: 1, edgeCount: 0 });

test("a binding brought back by Undo follows this page's later saves, renames and deletes", () => {
  const before = saved("r1");
  assert.deepEqual(latestBinding(new Map(), before), before, "a binding this page never changed comes back as it was");
  assert.equal(latestBinding(new Map([["g", saved("r2")]]), null), null);
  assert.deepEqual(latestBinding(new Map([["g", saved("r2", "Renamed")]]), before), saved("r2", "Renamed"));
  assert.equal(latestBinding(new Map([["g", null]]), before), null, "a deleted saved graph is no longer bound");
  assert.deepEqual(latestBinding(new Map([["other", null]]), before), before);
});

function dialog(open) {
  const calls = [];
  return { calls, open, showModal() { calls.push("showModal"); this.open = true; }, close() { calls.push("close"); this.open = false; } };
}

test("the native dialog follows the page's dialog state, also after the browser closed it", () => {
  const closed = dialog(false);
  assert.equal(syncDialogElement(closed, true), "opened");
  assert.equal(syncDialogElement(closed, true), null, "an open dialog is not shown again");
  closed.open = false; // The browser closed it (a second Escape cannot be prevented) while the page still shows it.
  assert.equal(syncDialogElement(closed, true), "opened");
  assert.deepEqual(closed.calls, ["showModal", "showModal"]);
  assert.equal(syncDialogElement(closed, false), "closed");
  assert.equal(syncDialogElement(closed, false), null);
  assert.deepEqual(closed.calls, ["showModal", "showModal", "close"]);
});
